// Caminho: gestores/servidor/Arcoll.WinUI3/Services/PenteFino/ResultsStore.cs
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using Microsoft.Data.Sqlite;
namespace Arcoll.WinUI3.Services.PenteFino;
/// <summary>SQLite e arquivos de auditoria restritos à raiz local do módulo.</summary>
public sealed class ResultsStore
{
    public string Root{get;}
    private readonly object _gate=new();
    private static readonly JsonSerializerOptions Json=new(){WriteIndented=true};
    public ResultsStore(string root){Root=System.IO.Path.GetFullPath(root);PathPolicy.RejectLinks(Root);Directory.CreateDirectory(Root);PathPolicy.RejectLinks(Root);
        if(OperatingSystem.IsWindows()){
            var acl=new System.Security.AccessControl.DirectorySecurity();acl.SetAccessRuleProtection(true,false);
            using var identity=System.Security.Principal.WindowsIdentity.GetCurrent();
            var administrators=new System.Security.Principal.SecurityIdentifier(System.Security.Principal.WellKnownSidType.BuiltinAdministratorsSid,null);
            acl.SetOwner(administrators);
            foreach(var sid in new[]{administrators,new System.Security.Principal.SecurityIdentifier(System.Security.Principal.WellKnownSidType.LocalSystemSid,null)})
                acl.AddAccessRule(new System.Security.AccessControl.FileSystemAccessRule(sid,System.Security.AccessControl.FileSystemRights.FullControl,System.Security.AccessControl.InheritanceFlags.ContainerInherit|System.Security.AccessControl.InheritanceFlags.ObjectInherit,System.Security.AccessControl.PropagationFlags.None,System.Security.AccessControl.AccessControlType.Allow));
            acl.AddAccessRule(new System.Security.AccessControl.FileSystemAccessRule(identity.User!,System.Security.AccessControl.FileSystemRights.ReadAndExecute,System.Security.AccessControl.InheritanceFlags.ContainerInherit|System.Security.AccessControl.InheritanceFlags.ObjectInherit,System.Security.AccessControl.PropagationFlags.None,System.Security.AccessControl.AccessControlType.Allow));
            System.IO.FileSystemAclExtensions.SetAccessControl(new DirectoryInfo(Root),acl);
        }
        using var db=Open();using var sql=db.CreateCommand();sql.CommandText="CREATE TABLE IF NOT EXISTS settings(id INTEGER PRIMARY KEY CHECK(id=1),json TEXT NOT NULL);CREATE TABLE IF NOT EXISTS reports(id TEXT PRIMARY KEY,at TEXT NOT NULL,json TEXT NOT NULL);CREATE TABLE IF NOT EXISTS undo(id TEXT PRIMARY KEY,session TEXT NOT NULL,at TEXT NOT NULL,json TEXT NOT NULL);CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY AUTOINCREMENT,at TEXT NOT NULL,json TEXT NOT NULL,previous TEXT NOT NULL,hash TEXT NOT NULL);";sql.ExecuteNonQuery();}
    private SqliteConnection Open(){PathPolicy.RejectLinks(Root);PathPolicy.RejectLinks(System.IO.Path.Combine(Root,"history.sqlite"));var db=new SqliteConnection(new SqliteConnectionStringBuilder{DataSource=System.IO.Path.Combine(Root,"history.sqlite"),Pooling=false}.ToString());db.Open();return db;}
    public static string Hash(string text)=>Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(text))).ToLowerInvariant();
    public static string FileHash(string path,bool shared=false){using var stream=new FileStream(path,FileMode.Open,FileAccess.Read,shared?FileShare.ReadWrite:FileShare.Read);return Convert.ToHexString(SHA256.HashData(stream)).ToLowerInvariant();}
    public string LocalPath(params string[] parts){var path=System.IO.Path.GetFullPath(System.IO.Path.Combine(new[]{Root}.Concat(parts).ToArray()));if(!path.StartsWith(Root+System.IO.Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new IOException("Caminho fora da área do Pente-Fino.");PathPolicy.RejectLinks(path);return path;}
    public Settings LoadSettings(){lock(_gate){using var db=Open();using var q=db.CreateCommand();q.CommandText="SELECT json FROM settings WHERE id=1";var text=q.ExecuteScalar()as string;return text is null?Settings.Default:JsonSerializer.Deserialize<Settings>(text)??Settings.Default;}}
    public void SaveSettings(Settings settings){lock(_gate){using var db=Open();using var q=db.CreateCommand();q.CommandText="INSERT INTO settings VALUES(1,$v) ON CONFLICT(id) DO UPDATE SET json=excluded.json";q.Parameters.AddWithValue("$v",JsonSerializer.Serialize(settings));q.ExecuteNonQuery();}}
    public void Save(ScanReport report){lock(_gate){using var db=Open();using var q=db.CreateCommand();q.CommandText="INSERT OR REPLACE INTO reports VALUES($id,$at,$json)";q.Parameters.AddWithValue("$id",report.Id);q.Parameters.AddWithValue("$at",report.At.ToString("O"));q.Parameters.AddWithValue("$json",JsonSerializer.Serialize(report));q.ExecuteNonQuery();}Atomic(LocalPath("last-report.json"),JsonSerializer.Serialize(report,Json));}
    public ScanReport? Last(){lock(_gate){using var db=Open();using var q=db.CreateCommand();q.CommandText="SELECT json FROM reports ORDER BY at DESC LIMIT 1";return q.ExecuteScalar()is string text?JsonSerializer.Deserialize<ScanReport>(text):null;}}
    public void Journal(UndoRecord entry){lock(_gate){using var db=Open();using var q=db.CreateCommand();q.CommandText="INSERT OR REPLACE INTO undo VALUES($id,$session,$at,$json)";q.Parameters.AddWithValue("$id",entry.Id);q.Parameters.AddWithValue("$session",entry.Session);q.Parameters.AddWithValue("$at",entry.At.ToString("O"));q.Parameters.AddWithValue("$json",JsonSerializer.Serialize(entry));q.ExecuteNonQuery();}}
    public List<UndoRecord> UndoEntries(){lock(_gate){using var db=Open();using var q=db.CreateCommand();q.CommandText="SELECT json FROM undo ORDER BY at DESC,rowid DESC";using var r=q.ExecuteReader();var entries=new List<UndoRecord>();while(r.Read())if(JsonSerializer.Deserialize<UndoRecord>(r.GetString(0))is{} e)entries.Add(e);return entries;}}
    public void Audit(string action,object detail){lock(_gate){using var db=Open();using var transaction=db.BeginTransaction();using var read=db.CreateCommand();read.Transaction=transaction;read.CommandText="SELECT hash FROM audit ORDER BY id DESC LIMIT 1";var previous=read.ExecuteScalar()as string??new string('0',64);var at=DateTimeOffset.UtcNow.ToString("O");var payload=JsonSerializer.Serialize(new{at,action,detail});var hash=Hash(previous+"\n"+payload);using var q=db.CreateCommand();q.Transaction=transaction;q.CommandText="INSERT INTO audit(at,json,previous,hash) VALUES($at,$json,$previous,$hash)";q.Parameters.AddWithValue("$at",at);q.Parameters.AddWithValue("$json",payload);q.Parameters.AddWithValue("$previous",previous);q.Parameters.AddWithValue("$hash",hash);q.ExecuteNonQuery();transaction.Commit();
        // O banco é a fonte transacional. O arquivo é uma projeção reparável dessa cadeia.
        using var output=new FileStream(LocalPath("audit.jsonl"),FileMode.Append,FileAccess.Write,FileShare.Read);
        using var writer=new StreamWriter(output,Encoding.UTF8,4096,true);writer.WriteLine(JsonSerializer.Serialize(new{payload=JsonSerializer.Deserialize<JsonElement>(payload),previous,hash}));writer.Flush();output.Flush(true);
    }}
    public bool VerifyAudit(){lock(_gate){using var db=Open();using var q=db.CreateCommand();q.CommandText="SELECT json,previous,hash FROM audit ORDER BY id";using var r=q.ExecuteReader();var previous=new string('0',64);var expected=new List<string>();while(r.Read()){if(r.GetString(1)!=previous||Hash(previous+"\n"+r.GetString(0))!=r.GetString(2))return false;expected.Add(JsonSerializer.Serialize(new{payload=JsonSerializer.Deserialize<JsonElement>(r.GetString(0)),previous=r.GetString(1),hash=r.GetString(2)}));previous=r.GetString(2);}var path=LocalPath("audit.jsonl");if(!File.Exists(path))return expected.Count==0;return File.ReadAllLines(path).Where(x=>x.Length>0).SequenceEqual(expected,StringComparer.Ordinal);}}
    private void RebuildAuditFile(SqliteConnection db){using var q=db.CreateCommand();q.CommandText="SELECT json,previous,hash FROM audit ORDER BY id";using var r=q.ExecuteReader();var lines=new StringBuilder();while(r.Read())lines.AppendLine(JsonSerializer.Serialize(new{payload=JsonSerializer.Deserialize<JsonElement>(r.GetString(0)),previous=r.GetString(1),hash=r.GetString(2)}));Atomic(LocalPath("audit.jsonl"),lines.ToString());}
    public static void Atomic(string path,string text){var temp=path+"."+Guid.NewGuid().ToString("N")+".tmp";try{using(var stream=new FileStream(temp,FileMode.CreateNew,FileAccess.Write,FileShare.None)){using var writer=new StreamWriter(stream,Encoding.UTF8,4096,true);writer.Write(text);writer.Flush();stream.Flush(true);}File.Move(temp,path,true);}finally{if(File.Exists(temp))File.Delete(temp);}}
    public string Export(ScanReport report,bool html){var folder=LocalPath("exports");Directory.CreateDirectory(folder);var path=LocalPath("exports",report.Id+(html?".html":".json"));if(!html)Atomic(path,JsonSerializer.Serialize(report,Json));else{static string E(string text)=>System.Net.WebUtility.HtmlEncode(text);var body=new StringBuilder("<!doctype html><html lang=pt-BR><meta charset=utf-8><title>Pente-Fino</title><style>body{font:14px system-ui;max-width:1100px;margin:40px auto;color:#172b44}table{width:100%;border-collapse:collapse}td,th{padding:8px;border:1px solid #ccd7e5;overflow-wrap:anywhere}h1,h2{color:#2563eb}</style><h1>Pente-Fino — relatório somente leitura</h1>");body.Append("<p>"+E(report.At.ToString("O"))+" · "+E(report.Id)+"</p>");foreach(var module in report.Modules){body.Append("<h2>"+E(module.Title)+"</h2><p>"+E(string.Join(" · ",module.Notes))+"</p><table><tr><th>Item</th><th>Caminho</th><th>Tamanho</th><th>Motivo</th><th>Ação proposta</th></tr>");foreach(var item in module.Items)body.Append("<tr><td>"+E(item.Title)+"</td><td>"+E(item.Path)+"</td><td>"+item.Bytes+" bytes</td><td>"+E(item.Reason)+"</td><td>"+E(item.Action)+"</td></tr>");body.Append("</table>");}body.Append("</html>");Atomic(path,body.ToString());}Audit("export",new{report.Id,format=html?"html":"json"});return path;}
}
